    with open(path, newline='') as f:
        return list(csv.DictReader(f))

techs = {r['technician_id']: r for r in read_csv(base/'data/technicians.csv')}
tickets_all = read_csv(base/'data/tickets.csv')
with open(base/'data/current_wave.json') as f:
    wave = json.load(f)
current_wave = int(wave['current_wave'])
current_time = int(wave['current_time_minute'])
freeze_until = int(wave['freeze_until_minute'])
visible_tickets = {r['ticket_id']: r for r in tickets_all if int(r['reveal_wave']) <= current_wave}
travel = {}
with open(base/'data/travel_times.csv', newline='') as f:
    for r in csv.DictReader(f):
        travel[(r['from_node'], r['to_node'])] = int(r['travel_minutes'])
replen = read_csv(base/'data/spare_replenishments.csv')
region_policies = {r['region']: float(r['min_p1_p2_service_rate']) for r in read_csv(base/'data/region_policies.csv')}
access_windows = defaultdict(list)
for r in read_csv(base/'data/access_windows.csv'):
    access_windows[r['ticket_id']].append((int(r['earliest_start_minute']), int(r['latest_start_minute']), r['window_id']))
staging = defaultdict(list)
for r in read_csv(base/'data/crew_staging_limits.csv'):
    staging[r['region']].append((int(r['start_minute']), int(r['end_minute']), int(r['max_active_crews']), r['interval_id'])) )

plan_path = base/'submissions/initial_plan.csv'
with open(plan_path, newline='') as f:
    reader = csv.reader(f)
    rows = list(reader)
header = rows[0]
plan = [dict(zip(header, row)) for row in rows[1:]]

expected_header = ['ticket_id','decision','primary_technician','assistant_technician','start_minute']
violations=[]
coverage=[]

def add_violation(family,key,rule,observed,required,suggestion):
    violations.append({
        'family': family,
        'key': key,
        'rule': rule,
        'observed': observed,
        'required': required,
        'suggestion': suggestion,
    })

# Coverage helper
covered=[]
def cover(family,status,detail=''):
    covered.append((family,status,detail))

if header == expected_header:
    cover('schema/nullability and key coverage','recomputed','header matches exact public schema')
else:
    add_violation('schema/nullability and key coverage','header','Exact CSV header',header,expected_header,'Rewrite export header to the exact public order/names.')

# parse skills
skill_levels={}
for tid, tr in techs.items():
    skills={}
    for item in tr['skills'].split('|'):
        name, lvl = item.split(':')
        skills[name]=int(lvl)
    skill_levels[tid]=skills

highest_seniority=max(int(t['seniority']) for t in techs.values())

# Key coverage / domains / nullability
ids=[r['ticket_id'] for r in plan]
count=Counter(ids)
for t,c in count.items():
    if c"'!=1:
        add_violation('"'schema/nullability and key coverage',f'ticket_id={t}','Each visible ticket must appear exactly once',f'appears {c} times','exactly once','Remove duplicates or add missing ticket rows so every visible ticket appears exactly once.')
missing=sorted(set(visible_tickets)-set(ids))
extra=sorted(set(ids)-set(visible_tickets))
for t in missing:
    add_violation('schema/nullability and key coverage',f'ticket_id={t}','Each visible ticket must appear exactly once','missing row','one row required','Add one plan row for the missing visible ticket.')
for t in extra:
    add_violation('schema/nullability and key coverage',f'ticket_id={t}','Use valid visible ticket IDs',t,'ticket_id in current visible ticket set','Replace with a valid visible ticket ID or remove the row.')
if not missing and not extra and all(c==1 for c in count.values()) and len(plan)==len(visible_tickets):
    cover('schema/nullability and key coverage','recomputed',f'{len(plan)} plan rows cover all {len(visible_tickets)} visible tickets exactly once')

# prepare durations and plan map
plan_map={}
for r in plan:
    plan_map[r['ticket_id']]=r
    dec=r['decision']
    if dec not in ('schedule','defer'):
        add_violation('identifier domains',f\"ticket_id={r['ticket_id']}\",'Decision domain',dec,'schedule or defer','Use only public decision values "'`schedule` or `defer`.'"')
        continue
    if dec=='schedule':
        if r['primary_technician'] not in techs:
            add_violation('identifier domains',f\"ticket_id={r['ticket_id']}\",'Primary technician ID domain',r['primary_technician'],'valid technician_id','Use a valid technician ID from technicians.csv.')
        if r['assistant_technician'] and r['assistant_technician'] not in techs:
            add_violation('identifier domains',f\"ticket_id={r['ticket_id']}\",'Assistant technician ID domain',r['assistant_technician'],'valid technician_id or blank','Use a valid technician ID or leave blank where permitted.')
        try:
            int(r['start_minute'])
        except Exception:
            add_violation('schema/nullability and key coverage',f\"ticket_id={r['ticket_id']}\",'Scheduled ticket must have integer start_minute',r['start_minute'],'integer minute','Populate start_minute with an integer minute for scheduled work.')
        if not r['primary_technician']:
            add_violation('schema/nullability and key coverage',f\"ticket_id={r['ticket_id']}\",'Scheduled ticket must have primary technician',r['primary_technician'],'nonblank primary_technician','Assign a valid primary technician.')
    else:
        if any(r[k] for k in ('primary_technician','assistant_technician','start_minute')):
            add_violation('schema/nullability and key coverage',f\"ticket_id={r['ticket_id']}\",'Deferred ticket must leave technician and start fields blank', {k:r[k] for k in ('primary_technician','assistant_technician','start_minute')}, 'all blank', 'Blank the technician and start fields for deferred tickets.')
if not [v for v in violations if v['family']=='identifier domains']:
    cover('identifier domains','recomputed','all ticket/technician identifiers and decision values are in-domain')

# ticket-level feasibility
factor={1:1.28,2:1.0,3:0.83}
assigned_by_tech=defaultdict(list)
part_usage=defaultdict(lambda: defaultdict(int))
late_pen=0.0
base_minutes_primary=defaultdict(int)
service_minutes_all_roles=defaultdict(int)

for tid,t in visible_tickets.items():
    row=plan_map.get(tid)
    if not row: 
        continue
    dec=row['decision']
    pri=t['priority']
    if pri=='P1' and dec"'!='"'schedule':
        add_violation('schema/nullability and key coverage',f'ticket_id={tid}','P1 tickets must be scheduled',dec,'schedule','Schedule every P1 ticket.')
    if dec"'!='"'schedule':
        continue
    start=int(row['start_minute'])
    primary=row['primary_technician']
    assistant=row['assistant_technician']
    tskills=skill_levels.get(primary,{})
    req=t['required_skill']
    plvl=tskills.get(req,0)
    if plvl<1:
        add_violation('time, location, readiness, setup, and non-overlap',f'ticket_id={tid}','Primary technician must have required skill',f'{primary}:{req} level {plvl}','level >= 1','Assign a primary technician with the required skill.')
        dur=None
    else:
        dur=math.ceil(int(t['base_service_minutes']) * factor[plvl])
    if int(t['two_technician_required'])==1:
        if not assistant:
            add_violation('time, location, readiness, setup, and non-overlap',f'ticket_id={tid}','Two-technician ticket must name an assistant technician',assistant,'nonblank distinct assistant_technician','Assign a distinct assistant technician.')
        elif assistant==primary:
            add_violation('time, location, readiness, setup, and non-overlap',f'ticket_id={tid}','Assistant technician must be distinct from primary',assistant,'distinct technician IDs','Assign a different assistant technician.')
    else:
        if assistant:
            add_violation('schema/nullability and key coverage',f'ticket_id={tid}','One-person scheduled ticket must leave assistant_technician blank',assistant,'blank','Blank assistant_technician on one-person tickets.')
    crew=[x for x in [primary,assistant] if x]
    if t['secondary_skill']:
        if not any(skill_levels.get(tech,{}).get(t['secondary_skill'],0)>=1 for tech in crew):
            add_violation('time, location, readiness, setup, and non-overlap',f'ticket_id={tid}','Crew must cover the secondary skill',f'crew {crew} lacks {t[\"secondary_skill\"]}','at least one crew member with required secondary skill','Assign or add a technician who covers the secondary skill.')
    if int(t['bucket_required'])==1:
        if not any(int(techs[tech]['bucket_truck'])==1 for tech in crew):
            add_violation('time, location, readiness, setup, and non-overlap',f'ticket_id={tid}','Crew must include a bucket truck when bucket_required=1',f'crew {crew} bucket flags {[techs[tech][\"bucket_truck\"] for tech in crew]}','at least one crew member with bucket_truck=1','Assign a crew including a bucket-truck technician.')
    if int(t['two_technician_required'])==1 and t['risk_class']=='high':
        if not any(int(techs[tech]['seniority'])==highest_seniority for tech in crew):
            add_violation('time, location, readiness, setup, and non-overlap',f'ticket_id={tid}','High-risk two-person work must include highest seniority tier',f'crew seniorities {[techs[tech][\"seniority\"] for tech in crew]}',f'at least one seniority {highest_seniority}','Assign at least one highest-tier technician to the crew.')
    if start < int(t['release_minute']):
        add_violation('time, location, readiness, setup, and non-overlap',f'ticket_id={tid}','Ticket start cannot be earlier than release_minute',start,f'>= {t[\"release_minute\"]}','Delay the start to the release minute or later.')
    if start < current_time:
        add_violation('frozen/nonanticipative decisions',f'ticket_id={tid}','Newly planned work cannot start before current replanning time',start,f'>= {current_time}','Shift the start to current_time_minute or later.')
    if access_windows[tid]:
        if not any(lo <= start <= hi for lo,hi,_ in access_windows[tid]):
            add_violation('time, location, readiness, setup, and non-overlap',f'ticket_id={tid}','Start must fall within an available access window',start,'inside one published [earliest_start_minute, latest_start_minute] window','Move the start into one of the allowed access windows.')
    if dur is not None:
        finish = start + dur
        if finish > int(t['deadline_minute']):
            add_violation('time, location, readiness, setup, and non-overlap',f'ticket_id={tid}','Finish cannot exceed hard deadline',finish,f'<= {t[\"deadline_minute\"]}','Start earlier or reassign to a faster qualified technician.')
        late=max(0, finish-int(t['due_minute']))
        late_pen += late*float(t['late_penalty_per_min'])
        assigned_by_tech[primary].append({'ticket_id':tid,'role':'primary','node':t['node_id'],'start':start,'end':finish})
        base_minutes_primary[primary]+=dur
        service_minutes_all_roles[primary]+=dur
        for part in ('part_ont','part_radio','part_battery','part_router'):
            part_usage[primary][part]+=int(t[part])
        if assistant:
            assigned_by_tech[assistant].append({'ticket_id':tid,'role':'assistant','node':t['node_id'],'start':start,'end':finish})
            service_minutes_all_roles[assistant]+=dur
        row['_duration']=dur
        row['_finish']=finish

# predecessor
for tid,t in visible_tickets.items():
    pred=t['predecessor_ticket_id']
    if pred and tid in plan_map and pred in plan_map and plan_map[tid]['decision']=='schedule' and plan_map[pred]['decision']=='schedule':
        s=int(plan_map[tid]['start_minute'])
        pred_finish=plan_map[pred].get('_finish')
        if pred_finish is not None and s < pred_finish + 15:
            add_violation('time, location, readiness, setup, and non-overlap',f'ticket_id={tid}','Ticket with predecessor must start at least 15 minutes after predecessor finishes',s,f'>= {pred_finish+15}','Delay the successor or accelerate the predecessor assignment.')

# Regional floors
visible_hp=defaultdict(int)
scheduled_hp=defaultdict(int)
for tid,t in visible_tickets.items():
    if t['priority'] in ('P1','P2'):
        visible_hp[t['region']]+=1
        if plan_map[tid]['decision']=='schedule':
            scheduled_hp[t['region']]+=1
for region,den in visible_hp.items():
    req=region_policies[region]
    rate=scheduled_hp[region]/den if den else 1.0
    if rate + 1e-12 < req:
        add_violation('capacities and scenario derates',f'region={region}','Minimum service floor for visible P1/P2 tickets',rate,f'>= {req}','Schedule more visible P1/P2 tickets in the region.')

# Inventory
replen_by_tech=defaultdict(lambda: defaultdict(int))
for r in replen:
    if int(r['wave']) <= current_wave:
        tech=r['technician_id']
        for part in ('part_ont','part_radio','part_battery','part_router'):
            replen_by_tech[tech][part]+=int(r[part])
for tech, usage in part_usage.items():
    tr=techs[tech]
    for part, used in usage.items():
        avail=int(tr[part]) + replen_by_tech[tech][part]
        if used > avail:
            add_violation('conservation and inventory',f'technician={tech},part={part}','Primary technician van stock cannot be over-consumed',used,f'<= {avail}','Reassign some primary tickets or add stock through an allowed replenishment wave.')

# Technician route replay
nonoverlap_checked=False
for tech, jobs in assigned_by_tech.items():
    jobs.sort(key=lambda x:(x['start'], x['end'], x['ticket_id']))
    tr=techs[tech]
    shift_start=int(tr['shift_start'])
    shift_end=int(tr['shift_end'])
    ot_limit=int(tr['overtime_limit'])
    home=tr['home_node']
    prev=None
    for i,job in enumerate(jobs):
        if prev is None:
            tt=travel.get((home, job['node']))
            if tt is None:
                add_violation('time, location, readiness, setup, and non-overlap',f'technician={tech},first_ticket={job[\"ticket_id\"]}','Travel time must exist from home to first job',f'missing arc {home}->{job[\"node\"]}','arc must exist in travel_times.csv','Use a route with published travel times.')
            else:
                earliest=shift_start + tt
                if job['start'] < earliest:
                    add_violation('time, location, readiness, setup, and non-overlap',f'technician={tech},first_ticket={job[\"ticket_id\"]}','Technician must be able to depart from home at shift_start and reach first job',job['start'],f'>= {earliest} (= shift_start {shift_start} + travel {tt})','Delay the first assignment or use a closer/later-starting technician.')
        else:
            nonoverlap_checked=True
            if job['start'] < prev['end']:
                add_violation('time, location, readiness, setup, and non-overlap',f'technician={tech},tickets={prev[\"ticket_id\"]}->{job[\"ticket_id\"]}','Technician cannot overlap active jobs',job['start'],f'>= previous end {prev[\"end\"]}','Resequence or reassign one of the overlapping jobs.')
            tt=travel.get((prev['node'], job['node']))
            if tt is None:
                add_violation('time, location, readiness, setup, and non-overlap',f'technician={tech},tickets={prev[\"ticket_id\"]}->{job[\"ticket_id\"]}','Travel time must exist between consecutive job nodes',f'missing arc {prev[\"node\"]}->{job[\"node\"]}','arc must exist in travel_times.csv','Use consecutive jobs connected by published travel times.')
            else:
                earliest=prev['end'] + tt
                if job['start'] < earliest:
                    add_violation('time, location, readiness, setup, and non-overlap',f'technician={tech},tickets={prev[\"ticket_id\"]}->{job[\"ticket_id\"]}','Technician must have enough turnaround/travel time between consecutive jobs',job['start'],f'>= {earliest} (= previous end {prev[\"end\"]} + travel {tt})','Delay the later job or reassign one of the tickets.')
        prev=job
    if jobs:
        tt=travel.get((jobs[-1]['node'], home))
        if tt is None:
            add_violation('time, location, readiness, setup, and non-overlap',f'technician={tech},last_ticket={jobs[-1][\"ticket_id\"]}','Travel time must exist from last job back home',f'missing arc {jobs[-1][\"node\"]}->{home}','arc must exist in travel_times.csv','Use a route with a published return-home travel time.')
        else:
            return_time=jobs[-1]['end'] + tt
            allowed=shift_end + ot_limit
            if return_time > allowed:
                add_violation('capacities and scenario derates',f'technician={tech}','Technician must return home within regular shift plus overtime limit',return_time,f'<= {allowed} (= shift_end {shift_end} + overtime_limit {ot_limit})','Reassign or reorder work, or use a technician with more remaining time.')

# Staging limits via event sweep
for region, intervals in staging.items():
    region_jobs=[]
    for tid,t in visible_tickets.items():
        if t['region']==region and plan_map[tid]['decision']=='schedule':
            region_jobs.append((plan_map[tid]['_finish'], -1, tid))
            region_jobs.append((int(plan_map[tid]['start_minute']), +1, tid))
    for lo,hi,cap,interval_id in intervals:
        events=[]
        for tid,t in visible_tickets.items():
            if t['region']"'!=region or plan_map[tid]['"'decision']"'!='"'schedule':
                continue
            s=int(plan_map[tid]['start_minute'])
            e=plan_map[tid]['_finish']
            if e <= lo or s >= hi:
                continue
            events.append((max(s,lo), +1, tid))
            events.append((min(e,hi), -1, tid))
        active=0
        for time,delta,tid in sorted(events, key=lambda x:(x[0], x[1])):
            active += delta
            if active > cap:
                add_violation('capacities and scenario derates',f'region={region},interval_id={interval_id}','Regional active-crew cap',active,f'<= {cap}','Move some overlapping jobs outside the capped interval or to another feasible time.')
                break

# coverage statuses
if not any(v['family']=='time, location, readiness, setup, and non-overlap' for v in violations):
    detail=[]
    detail.append('release, deadline, skills, crew composition, access windows, predecessor, route continuity, non-overlap, return-home checked')
    cover('time, location, readiness, setup, and non-overlap','recomputed','; '.join(detail))
if not any(v['family']=='conservation and inventory' for v in violations):
    cover('conservation and inventory','recomputed','primary-tech part consumption checked against initial stock plus visible replenishments')
if not any(v['family']=='capacities and scenario derates' for v in violations):
    extra=[]
    if staging:
        extra.append('regional staging caps event-swept')
    else:
        extra.append('no active staging-limit rows to test')
    extra.append('regional P1/P2 floors checked')
    cover('capacities and scenario derates','recomputed',', '.join(extra))
if current_wave==1:
    cover('frozen/nonanticipative decisions','not applicable','initial wave has no prior accepted artifact; current_time_minute=0 and freeze_until_minute=0')
else:
    cover('frozen/nonanticipative decisions','partial','current_time/freeze rules checked; prior accepted artifact not loaded in this run')
if current_wave==1:
    cover('reserves/ramps','not applicable','no public reserve or ramp constructs appear in the initial-wave data')
else:
    cover('reserves/ramps','not covered','no public reserve or ramp constructs identified')

# Objective accounting: compute what is directly derivable
# travel and labor monetization are under-specified in public prompt; lateness/deferral/change are explicit.
num_def=sum(1 for r in plan if r['decision']=='defer')
def_pen=sum(float(visible_tickets[r['ticket_id']]['deferral_penalty']) for r in plan if r['decision']=='defer')
change_pen=0.0
cover('objective accounting','partial',f'lateness penalty recomputed={late_pen:.2f}, deferral penalty recomputed={def_pen:.2f}, change penalty recomputed={change_pen:.2f}; travel/labor cost formula is not fully specified in public data')

print('COVERAGE')
for fam,status,detail in covered:
    print(f'{fam}\\t{status}\\t{detail}')
print('\\nVIOLATIONS')
if not violations:
    print('NONE')
else:
    for v in violations:
        print(v)

print('\\nSUMMARY')
print('violations', len(violations))
print('late_penalty', round(late_pen,2))
print('deferrals', num_def, 'def_penalty', round(def_pen,2))
for tech, jobs in sorted(assigned_by_tech.items()):
    jobs=sorted(jobs,key=lambda x:x['start'])
    if not jobs: continue
    tr=techs[tech]
    home=tr['home_node']
    return_t=jobs[-1]['end'] + travel[(jobs[-1]['node'], home)]
    print('TECH', tech, 'jobs', [(j['ticket_id'],j['role'],j['start'],j['end']) for j in jobs], 'return', return_t, 'shift_end', tr['shift_end'], 'ot_lim', tr['overtime_limit'])
    print(' parts', dict(part_usage[tech]))
